// Package storage keeps uploaded recordings. Everything else talks to the
// Store interface; Local is the development implementation. A production
// implementation (an S3-compatible bucket) plugs in here without touching the
// callers. Keys are generated by the server and checked here, so a client can
// never choose or traverse a path.
package storage

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
)

var (
	ErrNotFound  = errors.New("storage: not found")
	ErrBadOffset = errors.New("storage: write is not at the end of the object")
	ErrBadKey    = errors.New("storage: invalid key")
)

// Object is a readable stored file.
type Object interface {
	io.ReadSeekCloser
	Size() int64
}

type Store interface {
	// Append writes data at exactly `offset` (the current size; 0 creates the
	// object) and returns the new size. Anything else is ErrBadOffset, which
	// makes retried chunks safe: a repeated chunk is refused, not duplicated.
	Append(ctx context.Context, key string, offset int64, r io.Reader) (int64, error)
	Size(ctx context.Context, key string) (int64, error)
	Open(ctx context.Context, key string) (Object, error)
	Delete(ctx context.Context, key string) error // deleting a missing object is not an error
	// Keys lists every stored key, for orphan checks.
	Keys(ctx context.Context) ([]string, error)
}

var keyRe = regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$`)

// Key is the only shape of key that exists: <workspace uuid>/<media uuid>.
func Key(workspace, media fmt.Stringer) string { return workspace.String() + "/" + media.String() }

func CheckKey(k string) error {
	if !keyRe.MatchString(k) {
		return ErrBadKey
	}
	return nil
}

// Local stores files under a directory, one subdirectory per workspace.
type Local struct{ Dir string }

func (l *Local) path(key string) (string, error) {
	if err := CheckKey(key); err != nil {
		return "", err
	}
	return filepath.Join(l.Dir, filepath.FromSlash(key)), nil
}

func (l *Local) Append(_ context.Context, key string, offset int64, r io.Reader) (int64, error) {
	p, err := l.path(key)
	if err != nil {
		return 0, err
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o700); err != nil {
		return 0, err
	}
	f, err := os.OpenFile(p, os.O_WRONLY|os.O_CREATE, 0o600) // #nosec G304 -- p was built from a key that CheckKey validated
	if err != nil {
		return 0, err
	}
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		return 0, err
	}
	if st.Size() != offset {
		return st.Size(), ErrBadOffset
	}
	n, err := io.Copy(&offsetWriter{f: f, off: offset}, r)
	if err != nil {
		_ = f.Truncate(offset) // never leave a half-written chunk behind
		return offset, err
	}
	if err := f.Sync(); err != nil {
		return offset, err
	}
	return offset + n, nil
}

type offsetWriter struct {
	f   *os.File
	off int64
}

func (w *offsetWriter) Write(p []byte) (int, error) {
	n, err := w.f.WriteAt(p, w.off)
	w.off += int64(n)
	return n, err
}

func (l *Local) Size(_ context.Context, key string) (int64, error) {
	p, err := l.path(key)
	if err != nil {
		return 0, err
	}
	st, err := os.Stat(p)
	if errors.Is(err, os.ErrNotExist) {
		return 0, ErrNotFound
	}
	if err != nil {
		return 0, err
	}
	return st.Size(), nil
}

type localObject struct {
	*os.File
	size int64
}

func (o localObject) Size() int64 { return o.size }

func (l *Local) Open(_ context.Context, key string) (Object, error) {
	p, err := l.path(key)
	if err != nil {
		return nil, err
	}
	f, err := os.Open(p) // #nosec G304 -- p was built from a key that CheckKey validated
	if errors.Is(err, os.ErrNotExist) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	st, err := f.Stat()
	if err != nil {
		_ = f.Close()
		return nil, err
	}
	return localObject{f, st.Size()}, nil
}

func (l *Local) Delete(_ context.Context, key string) error {
	p, err := l.path(key)
	if err != nil {
		return err
	}
	if err := os.Remove(p); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func (l *Local) Keys(_ context.Context) ([]string, error) {
	var out []string
	err := filepath.WalkDir(l.Dir, func(p string, d os.DirEntry, err error) error {
		if err != nil {
			if errors.Is(err, os.ErrNotExist) {
				return nil
			}
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(l.Dir, p)
		if err != nil {
			return err
		}
		out = append(out, filepath.ToSlash(rel))
		return nil
	})
	return out, err
}
